const fs=require('fs');
const puppeteer=require('puppeteer-core');
const base='http://127.0.0.1:8000/index.html';
const vps=[{name:'1920x1080',width:1920,height:1080},{name:'1440x900',width:1440,height:900},{name:'768x1024',width:768,height:1024},{name:'390x844',width:390,height:844},{name:'360x800',width:360,height:800}];
const out={productSha:'bfdaeefcce715ff36bf8f9838b6401ffcc477b9c',cases:{},failures:[]};
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
(async()=>{const browser=await puppeteer.launch({headless:true,executablePath:process.env.CHROME,args:['--no-sandbox','--disable-dev-shm-usage','--autoplay-policy=no-user-gesture-required']});fs.mkdirSync('gate-a-live-caption',{recursive:true});for(const vp of vps){const p=await browser.newPage();await p.setViewport({width:vp.width,height:vp.height,deviceScaleFactor:1});await p.goto(base,{waitUntil:'load',timeout:30000});await p.evaluate(()=>document.fonts?.ready||Promise.resolve());await p.waitForFunction(()=>{const v=document.getElementById('holding-film');return v&&v.readyState>=2&&Number.isFinite(v.duration)&&v.duration>10},{timeout:15000});await p.evaluate(()=>{const v=document.getElementById('holding-film');const t=v.textTracks?.[0];if(t)t.mode='showing';v.muted=true;});const play=await p.evaluate(async()=>{const v=document.getElementById('holding-film');try{await v.play();return{ok:true}}catch(e){return{ok:false,error:String(e)}}});if(!play.ok){out.failures.push({viewport:vp.name,type:'play',detail:play});await p.close();continue}await p.waitForFunction(()=>{const v=document.getElementById('holding-film'),t=v?.textTracks?.[0];return v&&v.currentTime>=4.1&&v.currentTime<=7&&t&&t.mode==='showing'&&t.activeCues&&t.activeCues.length>0},{timeout:12000}).catch(()=>{});const d=await p.evaluate(()=>{const box=e=>{const q=e.getBoundingClientRect();return{left:q.left,top:q.top,right:q.right,bottom:q.bottom,width:q.width,height:q.height}};const v=document.getElementById('holding-film'),t=v.textTracks?.[0],cs=getComputedStyle(v);return{currentTime:v.currentTime,paused:v.paused,trackMode:t?.mode||null,activeCues:t?.activeCues?[...t.activeCues].map(c=>({text:c.text,start:c.startTime,end:c.endTime,line:c.line,position:c.position,size:c.size,align:c.align})):[],video:box(v),fit:cs.objectFit,timeLabel:document.querySelector('[data-film-time]')?.textContent.trim()||''}});await p.screenshot({path:`gate-a-live-caption/live-${vp.name}.png`});out.cases[vp.name]=d;if(!(d.trackMode==='showing'&&d.activeCues.length>0&&d.currentTime>=4&&d.currentTime<7))out.failures.push({viewport:vp.name,type:'cue-not-live',detail:d});await p.close()}fs.writeFileSync('gate-a-live-caption/report.json',JSON.stringify(out,null,2));console.log(JSON.stringify(out,null,2));await browser.close();if(out.failures.length)process.exit(2)})().catch(e=>{console.error(e);process.exit(1)});
